#!/usr/bin/env python3
"""Localize links only to pages already generated by the unpublished static pilot.

No link is allowed to create a new route, bypass publication policy, or copy
content from the production website. Unknown destinations stay on production.
"""
from __future__ import annotations

import html
import json
import posixpath
import re
from collections import Counter
from pathlib import Path
from urllib.parse import unquote, urlsplit
import sys

sys.path.insert(0, str(Path(__file__).resolve().parent))
import build_github_pages_legal_details_pilot as legal
import build_github_pages_qa_details_pilot as qa

ORIGIN = "kaigo-rules.vercel.app"
ATTR = re.compile(r'(\bhref=")([^"]+)(")')
SAFE_SERVICE = re.compile(r"^[a-z0-9-]+$")
SAFE_CHAPTER = SAFE_SERVICE
SAFE_FRAGMENT = re.compile(r"^[A-Za-z0-9_.:-]+$")


def destination(root: Path, href: str) -> tuple[str, Path, str] | None:
    parts = urlsplit(href)
    if (parts.scheme != "https" or parts.netloc != ORIGIN or parts.username
            or parts.password or not parts.path.startswith("/")):
        return None
    decoded = unquote(parts.path)
    if any(c in decoded for c in ("\\", "\x00")) or "/../" in decoded or decoded.endswith("/.."):
        return None
    path = decoded.rstrip("/") or "/"
    query = parts.query
    kind = ""
    target = None
    suffix = ""

    if path in {"/", "/services"} and not query:
        kind, target = "home", root / "index.html"
    elif path == "/databases/search":
        kind, target, suffix = "search", root / "databases/search/index.html", ("?" + query if query else "")
    elif path == "/qa":
        kind, target, suffix = "qa-search", root / "databases/search/qa.html", ("?" + query if query else "")
    elif path in {"/start", "/overview", "/guide", "/sources", "/handbook-sources",
                  "/fees/guidance", "/fees"} and not query:
        kind, target = "information", root / path.lstrip("/") / "index.html"
    else:
        match = re.fullmatch(r"/services/([a-z0-9-]+)", path)
        if match and not query:
            kind, target = "services", root / "services" / match[1] / "index.html"
        match = re.fullmatch(r"/handbook/([a-z0-9-]+)/([a-z0-9-]+)", path)
        if match and not query:
            kind, target = "handbook", root / "handbook" / match[1] / (match[2] + ".html")
        match = re.fullmatch(r"/qa/([A-Za-z0-9][A-Za-z0-9._-]{0,120})", path)
        if match and query in {"", "reader=1"}:
            kind = "qa-detail"
            target = root / "databases/search/qa-details" / match[1] / (
                "reader.html" if query == "reader=1" else "index.html")
        match = re.fullmatch(r"/fees/([a-z0-9]+(?:[.-][a-z0-9]+)*)", path)
        if match and not query:
            kind = "fee-detail"
            target = root / "fees" / match[1] / "index.html"
        try:
            key = legal.key_from_href(path + ("?" + query if query else ""))
        except ValueError:
            key = None
        if key:
            kind, target = "legal-detail", root / "databases/search" / legal.local_path(key)

    if not target or not target.is_file() or target.is_symlink():
        return None
    # Keep fragments only when the generated target contains the exact ID.
    if parts.fragment:
        fragment = unquote(parts.fragment)
        if not SAFE_FRAGMENT.fullmatch(fragment):
            return None
        target_text = target.read_text(encoding="utf-8")
        if not re.search(r'\bid="' + re.escape(html.escape(fragment, quote=True)) + r'"', target_text):
            return None
    else:
        fragment = ""
    return kind, target, suffix + (("#" + fragment) if fragment else "")


def localize(root: Path) -> dict:
    if not root.is_dir() or root.is_symlink():
        raise RuntimeError("Missing or symbolic-link pilot directory")
    pages = list(root.rglob("*.html"))
    if any(p.is_symlink() for p in pages):
        raise RuntimeError("Symlink in generated HTML")
    counts = Counter()
    changed = 0
    links = 0
    for source in pages:
        content = source.read_text(encoding="utf-8")

        def replace(match):
            nonlocal links
            current = html.unescape(match[2])
            if not current.startswith("https://" + ORIGIN + "/"):
                return match[0]
            found = destination(root, current)
            if not found:
                return match[0]
            kind, target, suffix = found
            relative = posixpath.relpath(target.relative_to(root).as_posix(),
                                       source.parent.relative_to(root).as_posix() or ".")
            links += 1
            counts[kind] += 1
            new_href = html.escape(relative + suffix, quote=True)
            return match[1] + new_href + match[3]

        updated = ATTR.sub(replace, content)
        if updated != content:
            source.write_text(updated, encoding="utf-8")
            changed += 1
    return {"pages_scanned": len(pages), "pages_changed": changed,
            "links_localized": links, "by_destination": dict(sorted(counts.items()))}
